export async function drainAndStop(clients: WebSocket[], servers: any[]): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    if (wss) await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

